const out = [];
async function fight(pat, ms=45000, fleeAt=6) {
  try {
    const r = await bot.attack(pat, 8000);
    if (!r.success) { out.push([String(pat), 'noatk', r.reason, r.message]); return; }
    const t0 = Date.now();
    while (Date.now() - t0 < ms) {
      const s = sdk.getState()?.player;
      if (!s) { await new Promise(r=>setTimeout(r,300)); continue; }
      if (s.combat?.inCombat === false) { out.push([String(pat), 'ended', 'hp', s.combat?.hitpoints]); return; }
      if ((s.combat?.hitpoints ?? 99) <= fleeAt) {
        out.push([String(pat), 'flee', s.combat?.hitpoints]);
        await sdk.sendWalk(s.worldX + 20, s.worldZ + 20, true);
        await new Promise(r=>setTimeout(r, 3000));
        out.push([String(pat), 'afterFlee hp', sdk.getState()?.player?.combat?.hitpoints]);
        return;
      }
      await new Promise(r=>setTimeout(r, 350));
    }
    out.push([String(pat), 'timeout', sdk.getState()?.player?.combat?.hitpoints]);
  } catch(e) { out.push([String(pat), 'err', String(e).slice(0,50)]); }
}
